from typing import Literal

from pyvkteamsclient.admin.base.client import BaseAdminClient
from pyvkteamsclient.tracer import tracer


class ReportsMethods(BaseAdminClient):
    @tracer.start_as_current_span("admin.reports.api_mchat_report")
    def api_mchat_report(self, method: Literal["GET", "POST"]):
        return self.request(method=method, url="/".join([self.base_url, "api/mchat/report"]))

    @tracer.start_as_current_span("admin.reports.api_mchat_report_download")
    def api_mchat_report_download(self, uuid: str):
        return self.get(path="api/mchat/report/download/", uuid=uuid)
